mapper.update:
update classic_delay_task
set status      = #{status},
    actual_time = #{actualTime}
where task_no = #{taskNo}

update classic_delay_task
set retry_count = retry_count + 1
where task_no = #{taskNo}

mapper.select:
select

from classic_delay_task
where status in (1, 2)
  and expect_time <= #{threshold}
order by expect_time asc
limit #{limit}
